// smooth noise
float noise(vec2 n) {
    const vec2 d = vec2(0., 1.0);
    vec2 b = floor(n);
    vec2 f = mix(vec2(0.0), vec2(1.0), fract(n));
    return mix(mix(n21(b), n21(b + d.yx), f.x), mix(n21(b + d.xy), n21(b + d.yy), f.x), f.y);
}
vec2 pMod2(inout vec2 p, vec2 size) {
	vec2 c = floor((p + size*0.5)/size);
	p = mod(p + size*0.5,size) - size*0.5;
	return c;
}

float smin(float a, float b, float k) {
  float h = clamp((a-b)/k * .5 + .5, 0.0, 1.0);
  return mix(a, b, h) - h*(1.-h)*k;
}

float opSmoothIntersection( float d1, float d2, float k ) {
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h); }


float gyro(vec3 p){


    float size = 3.;
    p *= size;
    return abs(.5*dot(sin(p),cos(p.xxx))/size)-.02;
}

float box(vec3 p, vec3 r) {
  vec3 d = abs(p) - r;
  return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}


float map(vec3 p) {

    float d = 1e9, d0 = 1e9;
    vec3 bp = p;

    vec2 cid = pMod2(p.xz, vec2(.335));

    p.y -= .2*SIN(length(cid) + tt);
    d = box(p, vec3(.15))-.002;


    bp.y += mix(1.8, -.15, S(0.0, 6., iTime));
    p = bp;

    p.y -= .2;

    p.y *= .7;

    p.xz *= rot(p.y*1.8*SIN(.2*tt));

    float g= abs(abs(abs(length(p)-1.)-.2) - 0.1)- 0.04;
    p.xy = sabsk(p.xy, .2);
    mat2 mr = rot(.25*tt);
    p.xz *= mr;
    p.yz *= mr;

    g = opSmoothIntersection(g ,gyro(p),.015);

    d = smin(d, g, .3);

    float c = length(bp-vec3(0, 0.3+.4*SIN(.5*PI+tt), 0)) -.01;
    g_glow += .5/(.9+pow(abs(c)*4., 20.));

    return d*.5;

}

vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}

// iq's shadow function
float softshadow( in vec3 ro, in vec3 rd, float mint, float maxt, float k ) {

    float res = 1.0;
    float ph = 1e20;
    for( float t=mint; t<maxt; )
    {
        float h = map(ro + rd*t);
        if( h<0.001 )
            return 0.0;
        float y = h*h/(2.0*ph);
        float d = sqrt(h*h-y*y);
        res = min( res, k*d/max(0.0,t-y) );
        ph = h;
        t += h;
    }
    return res;
}


// why not put the raymarcher in a separate function (;
vec3 raymarch(vec3 ro, vec3 rd, float steps) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;
    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        t += d;
        p += rd*d;
        if(abs(d) < 0.001 || t > 200.) break;
    }

   // g_p = p;

    return vec3(t, mat, d);
}



// from iq code
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}

vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {

    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}

